<script setup lang="ts">
import { ref } from 'vue'
const token=ref(localStorage.getItem('user_token')||'');const email=ref('');const password=ref('');const display=ref('');const mode=ref<'login'|'register'>('login');const profile=ref<any>(null);const error=ref('');const newDisplay=ref('')
async function submit(){error.value='';const path=mode.value==='login'?'/api/v1/auth/login':'/api/v1/auth/register';const body=mode.value==='login'?{username:email.value,password:password.value}:{email:email.value,password:password.value,display_name:display.value};const r=await fetch(path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});const j=await r.json();if(!r.ok){error.value=j.detail||'请求失败';return};token.value=j.data.access_token;localStorage.setItem('user_token',token.value);await load()}
async function load(){const r=await fetch('/api/v1/auth/me',{headers:{Authorization:`Bearer ${token.value}`}});if(r.ok){profile.value=(await r.json()).data;newDisplay.value=profile.value.display_name}else logout()}
async function saveProfile(){const r=await fetch('/api/v1/users/me',{method:'PATCH',headers:{Authorization:`Bearer ${token.value}`,'Content-Type':'application/json'},body:JSON.stringify({display_name:newDisplay.value})});if(r.ok)profile.value=(await r.json()).data;else error.value='保存失败'}
function logout(){localStorage.removeItem('user_token');token.value='';profile.value=null}
if(token.value)load()
</script>
<template><main><h1>账户中心</h1><section v-if="!token"><van-tabs v-model:active="mode"><van-tab title="登录" name="login"/><van-tab title="注册" name="register"/></van-tabs><van-field v-if="mode==='register'" v-model="display" label="昵称"/><van-field v-model="email" label="邮箱"/><van-field v-model="password" type="password" label="密码"/><van-button type="primary" block @click="submit">{{mode==='login'?'登录':'注册'}}</van-button><p>{{error}}</p></section><section v-else><van-cell title="账户 ID" :value="profile?.id"/><van-cell title="邮箱" :value="profile?.email"/><van-field v-model="newDisplay" label="昵称"/><van-button block type="primary" @click="saveProfile">保存资料</van-button><van-button block @click="logout">退出登录</van-button></section></main></template>
